"""Low level interaction functions for Review Image window"""

import squishtest
from interops.libraries.squish_actions import common
from interops.libraries.xvi.interactions.objects.xvi_objects import Xvi_MainPage
from interops.libraries.miscellaneous.decorators import log_decorator
from interops.libraries.xvi.interactions.common_objects_ops import set_text,get_text,find_any_object

class ReviewImageOps:
    '''
    ReviewImage handler
    '''
    stat = {
        "/": ["Approved" ,  Xvi_MainPage.review_Image_Approve_Button],
        "X": ["Disapproved",  Xvi_MainPage.review_Image_Disapprove_Button],
        "!": ["Review requested", Xvi_MainPage.review_Image_Request_review_Button],
        " ": ["Not reviewed", Xvi_MainPage.review_Image_Reset_status_Button],
        }
    def __init__(self) -> None:
        pass

    @property
    def from_patient(self):
        self._patient = get_text(Xvi_MainPage.review_Image_Current_Patient_Label)
        return self._patient

    @property
    def treatment(self):
        self._treatment = get_text(Xvi_MainPage.review_Image_Current_Treatment_Label)
        return self._treatment

    @property
    def field(self):
        self._field = get_text(Xvi_MainPage.review_Image_Current_Field_Label)
        return self._field

    @property
    def image(self):
        self._image = get_text(Xvi_MainPage.review_Image_Current_Image_Label)
        return self._image

    @property
    def reviewlog(self):
        self._reviewlog= get_text(Xvi_MainPage.review_Image_Review_log_Edit)
        return self._reviewlog

    @property
    def currentuser(self):
        self._currentuser = squishtest.waitForObject(Xvi_MainPage.review_Image_Current_user_RadioButton).checked
        return self._currentuser

    @currentuser.setter
    def currentuser(self, value):
        checked = squishtest.waitForObject(Xvi_MainPage.review_Image_Current_user_RadioButton).checked
        if checked != value:
            common.left_click_object(Xvi_MainPage.review_Image_Current_user_RadioButton)
        self._currentuser = value

    @property
    def alternateuser(self):
        self._alternateuser = get_text(Xvi_MainPage.review_Image_Alternate_user_Edit)
        return self._alternateuser

    @alternateuser.setter
    def alternateuser(self, value):
        set_text(Xvi_MainPage.review_Image_Alternate_user_Edit, value)
        self._alternateuser = value

    @property
    def password(self):
        self._password = get_text(Xvi_MainPage.review_Image_Password_Edit)
        return self._password

    @password.setter
    def password(self, value):
        set_text(Xvi_MainPage.review_Image_Password_Edit, value)
        self._password = value

    @property
    def status(self):
        reviewlog = self.reviewlog
        self._status = reviewlog.split('\n')[0].split(' - ')[-1].rstrip(':') if ' - ' in reviewlog else ""
        return self._status

    @property
    def comments(self):
        reviewlog = self.reviewlog
        lines = reviewlog.split('Software version: ')[0] if ' - ' in reviewlog else ""
        index = lines.find('\n')
        self._comments = lines[index+1:] if index > -1 else ""
        return self._comments

    @log_decorator
    def click_button(self, reviewtype: str, comments: str, confirm: bool, oktoclose: bool = True):
        '''
        Click a button on Review Image window for a given review type chosen from ['/','X','!', ' '], i.e., approved, disapprove, request review, reset status
        with comments to add, and if confirmed, OK will be clicked on the following window and status will be affected
        '''
        v = self.stat.get(reviewtype, None)
        if v:
            common.left_click_object(v[1])
        else:
            print("No button found by the given key")
            return
        comments_Edit = find_any_object([Xvi_MainPage.review_Image_Comments_Edit])
        set_text(comments_Edit, comments)
        if confirm:
            self.click_OK_button()
        else:
            self.click_Cancel_button()
        if oktoclose:
            self.click_OK_button()

    @log_decorator
    def click_OK_button(self):
        common.left_click_object(Xvi_MainPage.review_Image_OK_Button)

    @log_decorator
    def click_Cancel_button(self):
        common.left_click_object(Xvi_MainPage.review_Image_Cancel_Button)

    @log_decorator
    def click_Help_button(self):
        common.left_click_object(Xvi_MainPage.review_Image_Help_Button)
